const norm = $('Normalize Job').first().json;
const cardResult = $json || {};
const cardSql = cardResult.card?.dataset_query?.native?.query || cardResult.card?.native_query || cardResult.native_query || '';
const cardName = cardResult.card?.name || norm.anomaly?.cardTitle || '';
const tables = [];
const sqlText = typeof cardSql === 'string' ? cardSql : JSON.stringify(cardSql);
const matches = sqlText.matchAll(/(?:from|join)\s+`?([\w.]+)`?/gi);
for (const m of matches) {
  const t = m[1].replace(/[`"]/g, '').toLowerCase();
  if (t.includes('.')) tables.push(t);
}
const state = norm.state || {};
state.cardSql = sqlText.slice(0, 20000);
state.cardTables = [...new Set(tables)].slice(0, 10);
state.discoveredTables = state.cardTables;
state.verifiedTables = state.cardTables;
return [{ json: { ...norm, state } }];

const norm = $('Normalize Job').first().json;
const parsed = $('Parse Dify Response').first().json;
const decision = parsed.decision || {};
const raw = decision;
const text = (value, max, fallback = '') => typeof value === 'string' ? value.trim().slice(0, max) : fallback;
const list = (value, maxItems, maxLength) => Array.isArray(value) ? value.filter(item => typeof item === 'string').map(item => item.trim().slice(0, maxLength)).filter(Boolean).slice(0, maxItems) : [];
const confidence = ['low', 'medium', 'high'].includes(raw.confidence) ? raw.confidence : 'low';
const dataSideVerdict = ['data_issue', 'business_change', 'insufficient_evidence'].includes(raw.dataSideVerdict) ? raw.dataSideVerdict : 'insufficient_evidence';
const notificationAction = ['send', 'downgrade', 'enrich_only'].includes(raw.notificationAction) ? raw.notificationAction : 'enrich_only';
const chartVisibility = raw.chartVisibility === 'hide_verified_normal' ? 'hide_verified_normal' : 'show';
const verificationReason = chartVisibility === 'hide_verified_normal' ? text(raw.verificationReason, 600) : '';
const analysis = {
  summary: text(raw.summary, 1200, 'Evidence collection finished.'),
  evidence: list(raw.evidence, 5, 600),
  possibleCauses: list(raw.possibleCauses, 3, 600),
  verificationSteps: list(raw.verificationSteps, 3, 600),
  recommendedActions: list(raw.recommendedActions, 3, 600),
  confidence,
  limitations: text(raw.limitations, 1600, parsed.difyText?.slice(-500) || 'Evidence is bounded.'),
  dataSideVerdict,
  notificationAction,
  chartVisibility,
  verificationReason
};
return [{ json: {
  jobId: norm.jobId,
  runId: norm.context.runId,
  countryCode: norm.context.countryCode,
  anomalyIndex: Number(norm.context.anomalyIndex),
  analysis,
  evidence: { evidenceChain: [] }
} }];
